export type AQICategory = 'Good' | 'Moderate' | 'Unhealthy for Sensitive' | 'Unhealthy' | 'Very Unhealthy' | 'Hazardous';

export interface AirQualityData {
  city: string;
  country: string;
  latitude: number;
  longitude: number;
  timestamp: string;
  aqi: number;
  category: AQICategory;
  color: string;
  pm25: number; // ug/m3
  pm10: number; // ug/m3
  no2: number; // ug/m3
  ozone: number; // ug/m3
  temperature: number; // Celsius
  humidity: number; // %
  windSpeed: number; // km/h
  boundaryLayerHeight: number; // meters
  thermalInversionActive: boolean;
  optimalVentilationWindow: {
    start: string;
    end: string;
    reason: string;
    currentSafe: boolean;
  };
  hourly: {
    time: string;
    hourLabel: string;
    pm25: number;
    aqi: number;
    isVentilationWindow?: boolean;
  }[];
}

export type HouseholdType = 
  | 'single' 
  | 'couple' 
  | 'family_with_infants' 
  | 'family_with_elderly' 
  | 'multi_generation';

export type VulnerabilityCondition = 
